head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행한다.
    //1. Run the sample file.
    //Verify 1. 샘플파일이 정상적으로 실행되어진다.(이전에는 정상적으로 실행되어지지 않음 첨부이미지참조)
    //1. The sample file will be executed normally. (Previously, it will not run normally.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wframe1_spinner1___input').getValue() == ' 50'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
